function feedback(id="click"){if(id==="click"){const now=Date.now();if(now-lastClickSoundAt<90)return;lastClickSoundAt=now;}audio.activate().then(()=>audio.play(id));}
function escapeHTML(s){return String(s??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));}
