function tutorialAllows(type){if(!game||game.day!==1&&game.tutorialStep!==12||!game.tutorialStep)return true;const common=["PAUSE","RESUME","SKIP_TUTORIAL","DISMISS_STORY"];const permitted={2:["BUY_INGREDIENT","AID","SAVE_SAUCE","OPEN_SHOP"],3:["ACCEPT_ORDER"],4:["STRIKE","COMPLETE_STAGE","RETRY"],5:["COAT","COMPLETE_STAGE","RETRY"],6:["START_TIMER","STOP_TIMER","COMPLETE_STAGE","RETRY"],7:["SELECT_SAUCE","COMPLETE_STAGE","RETRY"],8:["START_TIMER","STOP_TIMER","COMPLETE_STAGE","RETRY"],9:["SELECT_PART","PLACE","COMPLETE_STAGE","SERVE","RETRY"],10:["REACTION_NEXT","REACTION_SKIP","DISMISS_REACTION"],11:["GO_UPGRADE","BUY_UPGRADE","NEXT_DAY"],12:["OPEN_SHOP"]};return common.includes(type)||(permitted[game.tutorialStep]||[]).includes(type);}
function storyText(event){let text=event.text;if(event.id==="day2_morning"&&game.unlockedUpgradeIds.includes("fryer"))text=event.textIfFryer;if(event.id==="day3_morning"&&game.unlockedUpgradeIds.includes("chairs"))text=event.textIfChairs;if(event.id==="day7_result")text=game.reputation>=80?event.textIfReputation80:game.reputation>=60?event.textIfReputation60:game.reputation>=30?event.textIfReputation30:event.textIfReputationBelow30;const career=game.careerLedger,daily=game.dailyLedger;return text.replaceAll("{{provided}}",String(career.providedCount+daily.providedCount)).replaceAll("{{sales}}",yen(career.salesYen+daily.salesYen).replace(/円$/,""));}
function storyRevealMarkup(event,text,tag,cls=""){return '<'+tag+' class="'+cls+'" data-story-reveal data-story-id="'+escapeHTML(event.id)+'" data-full-text="'+escapeHTML(text)+'" aria-label="'+escapeHTML(text)+'"></'+tag+'>';}
function startStoryReveal(){
const activeId=game?.activeStoryEventId;
if(!activeId){if(storyRevealTimer!==null)clearTimeout(storyRevealTimer);storyRevealTimer=null;storyRevealId=null;storyRevealIndex=0;return;}
if(storyRevealTimer!==null)clearTimeout(storyRevealTimer);storyRevealTimer=null;
if(game.overlay)return;
const targets=[...document.querySelectorAll("[data-story-reveal]")].filter(el=>el.dataset.storyId===activeId);
if(!targets.length)return;
const text=targets[0].dataset.fullText||"",chars=Array.from(text);
if(storyRevealId!==activeId){storyRevealId=activeId;storyRevealIndex=0;}
if(settings.reduceMotion||settings.skipAnimations||settings.textSpeed==="instant")storyRevealIndex=chars.length;
const paint=()=>targets.forEach(el=>{el.textContent=chars.slice(0,storyRevealIndex).join("");el.setAttribute("aria-label",text);});
paint();if(storyRevealIndex>=chars.length)return;
const delay=settings.textSpeed==="slow"?70:35;
const tick=()=>{storyRevealTimer=null;if(game?.activeStoryEventId!==activeId)return;const current=[...document.querySelectorAll("[data-story-reveal]")].filter(el=>el.dataset.storyId===activeId);if(!current.length)return;storyRevealIndex=Math.min(chars.length,storyRevealIndex+1);current.forEach(el=>{el.textContent=chars.slice(0,storyRevealIndex).join("");el.setAttribute("aria-label",text);});if(storyRevealIndex<chars.length)storyRevealTimer=setTimeout(tick,delay);};
storyRevealTimer=setTimeout(tick,delay);
}
function revealStoryBeforeDismiss(){if(!game?.activeStoryEventId||storyRevealId!==game.activeStoryEventId)return false;const event=storyEvents.find(item=>item.id===game.activeStoryEventId);if(!event)return false;const length=Array.from(storyText(event)).length;if(storyRevealIndex>=length)return false;storyRevealIndex=length;startStoryReveal();return true;}
function continueStoryEvent(){if(revealStoryBeforeDismiss())return;run("DISMISS_STORY");}
function storyDialog(){const event=storyEvents.find(item=>item.id===game?.activeStoryEventId);if(!event)return "";const portrait=event.speakerId==="owner"?pic(art.owner(event.portraitAssetId),"story-portrait",event.speakerLabel):pic(art.customer(event.speakerId,event.portraitAssetId),"story-portrait",event.speakerLabel);return '<div class="overlay story-overlay"><section class="modal card story-modal" role="dialog" aria-modal="true" aria-labelledby="story-title">'+portrait+'<div class="story-copy"><p class="story-speaker">'+escapeHTML(event.speakerLabel)+'</p><h2 id="story-title">'+escapeHTML(event.title)+'</h2>'+storyRevealMarkup(event,storyText(event),"p","story-text")+btn("つづける","story-dismiss",'class="primary"')+'</div></section></div>';}
function renderTutorialGuide(){document.querySelectorAll(".tutorial-dimmer,.tutorial-banner").forEach(el=>el.remove());const guide=tutorialGuide();if(!guide)return;if(game.day===1&&game.phase==="RESULT"){try{localStorage.setItem("katsumeshi_tutorial_completed_v1","1");}catch{}}const target=guide.target;if(target){const rect=target.getBoundingClientRect(),dimmer=document.createElement("div");dimmer.className="tutorial-dimmer";dimmer.setAttribute("aria-hidden","true");dimmer.style.setProperty("--cx",(rect.left+rect.width/2)+"px");dimmer.style.setProperty("--cy",(rect.top+rect.height/2)+"px");dimmer.style.setProperty("--rx",Math.max(100,rect.width/2+32)+"px");dimmer.style.setProperty("--ry",Math.max(58,rect.height/2+28)+"px");document.body.append(dimmer);target.classList.add("tutorial-focus");}const banner=document.createElement("aside");banner.className="tutorial-banner";banner.setAttribute("role","status");banner.innerHTML='<strong>'+escapeHTML(guide.title)+'</strong><span>'+escapeHTML(guide.text)+'</span>';const story=storyEvents.find(event=>event.id===game.activeStoryEventId);if(story){const note=document.createElement("div");note.className="tutorial-story";note.innerHTML='<strong>'+escapeHTML(story.title)+'</strong>'+storyRevealMarkup(story,storyText(story),"span");const acknowledge=document.createElement("button");acknowledge.className="tutorial-story-ack";acknowledge.textContent="会話を確認";acknowledge.addEventListener("click",continueStoryEvent);note.append(acknowledge);banner.append(note);}let seen=false;try{seen=localStorage.getItem("katsumeshi_tutorial_completed_v1")==="1";}catch{}if(seen&&!story){const skip=document.createElement("button");skip.className="tutorial-skip";skip.textContent="チュートリアルをスキップ";skip.addEventListener("click",()=>{feedback();run("SKIP_TUTORIAL");});banner.append(skip);}document.body.append(banner);}
