const morphTpl=document.createElement("template");
function morphAttrs(x,y){for(const {name} of [...x.attributes])if(!y.hasAttribute(name))x.removeAttribute(name);for(const {name,value} of [...y.attributes])if(x.getAttribute(name)!==value)x.setAttribute(name,value);if(x.tagName==="INPUT"){if(x!==document.activeElement&&y.hasAttribute("value")&&x.value!==y.getAttribute("value"))x.value=y.getAttribute("value");if(x.checked!==y.hasAttribute("checked"))x.checked=y.hasAttribute("checked");}}
function morphChildren(a,b){const an=[...a.childNodes],bn=[...b.childNodes];for(let k=0;k<bn.length;k++){const x=an[k],y=bn[k];if(!x){a.appendChild(y);continue;}if(x.nodeType!==y.nodeType||x.nodeName!==y.nodeName){a.replaceChild(y,x);continue;}if(x.nodeType!==1){if(x.nodeValue!==y.nodeValue)x.nodeValue=y.nodeValue;continue;}morphAttrs(x,y);morphChildren(x,y);if(x.tagName==="SELECT"){const sel=y.querySelector("option[selected]");if(sel&&x.value!==sel.value)x.value=sel.value;}}for(let k=an.length-1;k>=bn.length;k--)an[k].remove();}
function morphInto(root,html){morphTpl.innerHTML=html;swapIcons(morphTpl.content);morphChildren(root,morphTpl.content);}
function render(){
let html=screen==="TITLE"?titlePage():screen==="HELP"?help():screen==="CREDITS"?credits():screen==="SETTINGS"?settingsPage():game?(game.phase==="MORNING"?morning():game.phase==="OPEN"?shop():game.phase==="COOK"?cooking():game.phase==="REACTION"?reaction():game.phase==="RESULT"?result():upgrades()):titlePage();
const tutorialPriority=!!(game?.tutorialStep&&(game.day===1||game.day===2&&game.tutorialStep===12));if(game?.activeStoryEventId&&screen==="GAME"&&!tutorialPriority)html+=storyDialog();
if(game?.overlay&&screen==="GAME")html+=pauseDialog();
if(toast)html+='<div class="toast" role="status">'+escapeHTML(toast)+'</div>';
morphInto(app,html);syncReactionTimer();scheduleAutoTake();
const musicPage=screen==="GAME"||(screen==="SETTINGS"&&settingsReturnScreen==="GAME");const phase=game?.phase;audio.setTrack(musicPage?(phase==="COOK"?"cooking":["RESULT","UPGRADE"].includes(phase)?"result":"shop"):"title");audio.setFrying(!!(musicPage&&!game?.overlay&&phase==="COOK"&&game.cookingSession?.stageIndex===2&&game.cookingSession.stageInput.timerStarted));
renderTutorialGuide();startStoryReveal();
}
function dbOpen(){return new Promise((resolve,reject)=>{const r=indexedDB.open("katsumeshi_game_v1",1);r.onupgradeneeded=()=>r.result.createObjectStore("saves");r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function migrateSave(raw){if(!raw||typeof raw!=="object"||Array.isArray(raw))return raw;const next=JSON.parse(JSON.stringify(raw));if(Array.isArray(next.orders))for(const order of next.orders)if(order&&typeof order==="object"&&!Object.hasOwn(order,"qualityBreakdown"))order.qualityBreakdown=null;if(!Object.hasOwn(next,"reactionStage"))next.reactionStage=next.phase==="REACTION"?"resultVisible":null;if(next.cookingSession?.stageInput&&!Object.hasOwn(next.cookingSession.stageInput,"selectedComponentId"))next.cookingSession.stageInput.selectedComponentId=null;if(!Object.hasOwn(next,"activeStoryEventId"))next.activeStoryEventId=null;if(next.activeStoryEventId&&!storyEvents.some(event=>event.id===next.activeStoryEventId)){if(Array.isArray(next.seenStoryEventIds)&&!next.seenStoryEventIds.includes(next.activeStoryEventId))next.seenStoryEventIds.push(next.activeStoryEventId);next.activeStoryEventId=null;}if(!Object.hasOwn(next,"tutorialStep")){if(next.day===1){if(next.phase==="MORNING")next.tutorialStep=2;else if(next.phase==="OPEN")next.tutorialStep=next.tutorialFirstServed?0:3;else if(next.phase==="COOK")next.tutorialStep=Math.min(9,4+(next.cookingSession?.stageIndex||0));else if(next.phase==="REACTION")next.tutorialStep=next.tutorialFirstServed?0:10;else next.tutorialStep=11;}else next.tutorialStep=0;}return next;}
async function dbRead(){const db=await dbOpen();return new Promise((resolve,reject)=>{const tx=db.transaction("saves","readonly"),store=tx.objectStore("saves"),main=store.get("main"),backup=store.get("backup");tx.oncomplete=()=>{const inspect=raw=>{const value=migrateSave(raw);return{value,errors:value?validateSave(value,saveSchema,config):["save missing"]};};const m=inspect(main.result),b=inspect(backup.result);db.close();resolve({main:m,backup:b});};tx.onerror=()=>{db.close();reject(tx.error);};tx.onabort=()=>{db.close();reject(tx.error||new Error("load aborted"));};});}
async function dbWrite(snapshot){
const errors=validateSave(snapshot,saveSchema,config);if(errors.length)throw Error("保存データの整合性エラー: "+errors.slice(0,4).join(" / "));
const db=await dbOpen();
return new Promise((resolve,reject)=>{
const tx=db.transaction("saves","readwrite"),store=tx.objectStore("saves"),mainReq=store.get("main"),backupReq=store.get("backup");let mainReady=false,backupReady=false;
const commit=()=>{if(!mainReady||!backupReady)return;const previous=migrateSave(mainReq.result),backup=backupReq.result;if(previous&&!validateSave(previous,saveSchema,config).length)store.put(previous,"backup");else if(backup===undefined)store.put(snapshot,"backup");store.put(snapshot,"main");};
mainReq.onsuccess=()=>{mainReady=true;commit();};backupReq.onsuccess=()=>{backupReady=true;commit();};
tx.oncomplete=()=>{db.close();resolve();};tx.onabort=()=>{db.close();reject(tx.error||new Error("save aborted"));};tx.onerror=()=>{db.close();reject(tx.error||new Error("save failed"));};
});
}
async function dbProbeWrite(){const db=await dbOpen();return new Promise((resolve,reject)=>{const tx=db.transaction("saves","readwrite"),store=tx.objectStore("saves"),key="__write_probe__";store.put(true,key);store.delete(key);tx.oncomplete=()=>{db.close();resolve();};tx.onabort=()=>{db.close();reject(tx.error||new Error("write probe aborted"));};tx.onerror=()=>{db.close();reject(tx.error||new Error("write probe failed"));};});}
async function save(){if(!game)return;const version=dirtyVersion,snapshot=JSON.parse(JSON.stringify(game));snapshot.revision=++revisionCounter;snapshot.savedAtIso=new Date().toISOString();const pending=saveChain.catch(()=>{}).then(()=>dbWrite(snapshot));saveChain=pending;try{await pending;if(game&&game.day===snapshot.day&&game.revision<snapshot.revision)game.revision=snapshot.revision;if(dirtyVersion===version)saveDirty=false;savedGameExists=true;lastSaveAt=Date.now();}catch(e){saveDirty=true;toast="⚠️ セーブに失敗しました。ブラウザの保存設定をご確認ください。";render();throw e;}}
function run(type,payload={}){if(!game)return false;if(!tutorialAllows(type)){notify("チュートリアルの案内に沿って進めてください。");return false;}const r=dispatch(game,{type,payload,targetDay:game.day,id:"cmd-"+Date.now()+"-"+(++counter)},config);if(!r.ok){notify(r.error);feedback("error");return false;}game=r.state;toast="";render();feedback("click");if(type==="BUY_INGREDIENT"||type==="BUY_UPGRADE")feedback("purchase");if(type==="SERVE"){feedback("serve");feedback("rank_"+game.lastReactionRank.toLowerCase());}saveDirty=true;dirtyVersion++;if(!["RESUME","STRIKE","COAT","PLACE","START_TIMER","STOP_TIMER","SELECT_SAUCE","TICK"].includes(type))save().catch(()=>{});return true;}
function loadDraft(){const s=game?.sauces.find(s=>s.id===draftId);draft=s?{...s.taste}:{sweetness:50,richness:60,acidity:40};}
app.addEventListener("input",e=>{const name=e.target.dataset.range;if(name){draft[name]=Number(e.target.value);const output=$("#o-"+name);if(output)output.textContent=draft[name];return;}const setting=e.target.dataset.setting;if(setting==="bgm"||setting==="se"){settings[setting]=Number(e.target.value);e.target.nextElementSibling.textContent=settings[setting]+"%";audio.setVolumes(settings.bgm,settings.se);persistSettings();}});
app.addEventListener("change",e=>{if(e.target.id==="sauce-slot"){draftId=e.target.value;loadDraft();render();return;}const setting=e.target.dataset.setting;if(setting==="reduceMotion"){settings.reduceMotion=e.target.checked;document.documentElement.classList.toggle("reduce-motion",settings.reduceMotion);}else if(setting==="skipAnimations"){settings.skipAnimations=e.target.checked;document.documentElement.classList.toggle("skip-animations",settings.skipAnimations);if(settings.skipAnimations)startStoryReveal();}else if(setting==="textSpeed"){settings.textSpeed=e.target.value;startStoryReveal();}else return;persistSettings();});
app.addEventListener("pointerdown",e=>{const zone=e.target.closest(".coat-zone");if(e.button!==0||!zone||game?.phase!=="COOK"||game?.cookingSession?.stageIndex!==1||game.overlay)return;e.preventDefault();const pointerId=e.pointerId;coatStroke={pointerId,zone:Number(zone.dataset.zone),cells:[],seen:new Set(),zoneEl:zone,lastX:e.clientX,lastY:e.clientY};zone.setPointerCapture?.(pointerId);const cell=e.target.closest("[data-coat-cell]");if(cell)collectCoatCell(cell);});
function collectCoatCell(cell){if(!coatStroke||!cell)return;const z=Number(cell.dataset.zone),n=Number(cell.dataset.cell),key=z+":"+n;if(!Number.isInteger(z)||!Number.isInteger(n)||coatStroke.seen.has(key))return;coatStroke.seen.add(key);coatStroke.cells.push([z,n]);cell.classList.add("preview");}
app.addEventListener("pointermove",e=>{if(!coatStroke||e.pointerId!==coatStroke.pointerId)return;const dx=e.clientX-coatStroke.lastX,dy=e.clientY-coatStroke.lastY,steps=Math.max(1,Math.ceil(Math.hypot(dx,dy)/4));for(let i=1;i<=steps;i++){const x=coatStroke.lastX+dx*i/steps,y=coatStroke.lastY+dy*i/steps,cell=document.elementFromPoint(x,y)?.closest?.("[data-coat-cell]");collectCoatCell(cell);}coatStroke.lastX=e.clientX;coatStroke.lastY=e.clientY;});
function finishCoatStroke(commit){if(!coatStroke)return;const stroke=coatStroke;coatStroke=null;suppressCoatClickUntil=Date.now()+350;if(commit){if(stroke.cells.length)run("COAT",{cells:stroke.cells});else run("COAT",{zone:stroke.zone});}else for(const cell of app.querySelectorAll(".coat-cell.preview"))cell.classList.remove("preview");}
app.addEventListener("pointerup",e=>{if(coatStroke&&e.pointerId===coatStroke.pointerId){const inside=document.elementFromPoint(e.clientX,e.clientY)?.closest?.(".coat-cutlet");finishCoatStroke(!!inside);}});
app.addEventListener("pointercancel",e=>{if(coatStroke&&e.pointerId===coatStroke.pointerId)finishCoatStroke(false);});
app.addEventListener("pointerdown",e=>{if(e.button!==0||game?.phase!=="COOK"||game.overlay)return;const boilBtn=e.target.closest(".boil-btn");if(boilBtn&&!boilBtn.disabled){e.preventDefault();boilPress();return;}const pad=e.target.closest(".prep-pad");if(!pad||game.cookingSession?.stageIndex>1)return;e.preventDefault();pad.setPointerCapture?.(e.pointerId);pad.classList.add("dragging");prepStroke={id:e.pointerId,pad,minX:e.clientX,maxX:e.clientX,len:0,lx:e.clientX,ly:e.clientY,rect:(pad.querySelector(".prep-meat")||pad).getBoundingClientRect()};});
app.addEventListener("pointermove",e=>{const st=prepStroke;if(!st||e.pointerId!==st.id)return;st.len+=Math.hypot(e.clientX-st.lx,e.clientY-st.ly);st.lx=e.clientX;st.ly=e.clientY;st.minX=Math.min(st.minX,e.clientX);st.maxX=Math.max(st.maxX,e.clientX);prepPreview(st.pad,strokeEffect(st,st.rect));});
document.addEventListener("pointerup",e=>{if(boilPressAt&&Date.now()-boilPressAt>350&&game?.cookingSession?.stageIndex===4&&game.cookingSession.stageInput.timerStarted)boilStop();boilPressAt=0;const st=prepStroke;if(!st||e.pointerId!==st.id)return;prepStroke=null;st.pad.classList.remove("dragging");if(game?.phase==="COOK"&&game.cookingSession?.stageIndex<=1)commitPrep(st);});
document.addEventListener("pointercancel",e=>{if(prepStroke&&e.pointerId===prepStroke.id){prepStroke=null;render();}});
app.addEventListener("keydown",e=>{const pad=e.target.closest?.(".prep-pad");if(!pad||(e.key!=="Enter"&&e.key!==" ")||game?.cookingSession?.stageIndex>1)return;e.preventDefault();e.stopPropagation();const r=pad.querySelector(".prep-meat").getBoundingClientRect();commitPrep({len:r.width*0.7,minX:r.left,maxX:r.right,rect:r});});
let p6DraggedComponent=null;app.addEventListener("dragstart",e=>{const part=e.target.closest?.("[data-act=select-part]");if(!part||part.disabled||game?.phase!=="COOK"||game.cookingSession?.stageIndex!==5)return;p6DraggedComponent=part.dataset.component;e.dataTransfer?.setData("text/plain",p6DraggedComponent);if(e.dataTransfer)e.dataTransfer.effectAllowed="move";});app.addEventListener("dragover",e=>{const slot=e.target.closest?.("[data-act=place]");if(slot&&!slot.disabled&&p6DraggedComponent){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect="move";}});app.addEventListener("drop",e=>{const slot=e.target.closest?.("[data-act=place]");if(!slot||slot.disabled||!p6DraggedComponent)return;e.preventDefault();const part=p6DraggedComponent;p6DraggedComponent=null;if(run("SELECT_PART",{componentId:part}))run("PLACE",{slot:slot.dataset.slot});});app.addEventListener("dragend",()=>{p6DraggedComponent=null;});app.addEventListener("click",async e=>{
const el=e.target.closest("[data-act]");if(!el)return;const act=el.dataset.act;
if(el.disabled)return;feedback("click");
if(act==="strike"){const r=el.getBoundingClientRect();run("STRIKE",{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width))});return;}
if(act==="new"){const warnings=[];if(savedGameExists)warnings.push("保存済みのゲームを上書きします。");if(!storageWriteAvailable)warnings.push("この環境ではセーブできない可能性があります。ページを閉じると進行が失われます。");if(warnings.length&&!confirm(warnings.join("\n")+"\n新しく始めますか？"))return;game=createGame(config);revisionCounter=0;dirtyVersion++;screen="GAME";resetDraft();render();await save().catch(()=>{});return;}
if(act==="continue"){try{const saves=await dbRead();if(saves.main.errors.length===0)game=saves.main.value;else if(saves.backup.errors.length===0){if(!confirm("最新のセーブに不整合があります。バックアップから復旧しますか？\n復旧できるデータ: "+new Date(saves.backup.value.savedAtIso).toLocaleString("ja-JP")))return;game=saves.backup.value;toast="バックアップから復旧しました。現在の状態を確認してから続けてください。";}else throw Error("有効なセーブもバックアップもありません。既存データは削除していません。");loadDraft();game.overlay={kind:"PAUSE"};revisionCounter=game.revision||0;dirtyVersion++;screen="GAME";render();}catch(e){notify("ロード失敗："+e.message);}return;}

if(act==="quit"){window.close();setTimeout(()=>notify("ブラウザのタブを閉じるとゲームを終了します。"),150);return;}
if(act==="help"){screen="HELP";render();return;}
if(act==="credits"){screen="CREDITS";render();app.querySelector('[data-act="back-title"]')?.focus();return;}
if(act==="back-title"){screen="TITLE";render();return;}
if(act==="settings"){settingsReturnScreen=screen;screen="SETTINGS";render();app.querySelector('[role="dialog"] input[data-setting="bgm"]')?.focus();return;}
if(act==="settings-back"){screen=settingsReturnScreen;render();return;}
if(act==="story-dismiss"){continueStoryEvent();return;}
if(act==="pause"){cancelTransientInput();run("PAUSE");return;}
if(act==="resume"){run("RESUME");return;}
if(act==="save-quit"){if(saveQuitInProgress)return;saveQuitInProgress=true;render();try{await save();screen="TITLE";game=null;saveQuitInProgress=false;render();}catch{saveQuitInProgress=false;render();}return;}
if(act==="buy"){run("BUY_INGREDIENT",{ingredient:el.dataset.ingredient,qty:Number(el.dataset.qty)});return;}
if(act==="aid"){run("AID");return;}
if(act==="save-sauce"){run("SAVE_SAUCE",{id:draftId,taste:{...draft}});return;}
if(act==="open"){const saved=game.sauces.find(s=>s.id===draftId)?.taste||{sweetness:50,richness:60,acidity:40};if(["sweetness","richness","acidity"].some(k=>draft[k]!==saved[k])&&!confirm("保存していないたれの配合を破棄して開店しますか？"))return;run("OPEN_SHOP");return;}
if(act==="accept"){run("ACCEPT_ORDER",{orderId:el.dataset.order});return;}
if(act==="coat"){if(Date.now()<suppressCoatClickUntil)return;run("COAT",{zone:Number(el.dataset.zone)});return;}
if(act==="coat-full"){run("COAT",{zone:Number(el.dataset.zone),full:true});return;}
if(act==="fry-tap"){fryTap();return;}
if(act==="boil"){if(e.detail===0)boilPress();return;}
if(act==="plate-up"){plateUp();return;}
if(act==="start-timer"){run("START_TIMER");return;}
if(act==="stop-timer"){run("STOP_TIMER");return;}
if(act==="choose-sauce"){run("SELECT_SAUCE",{id:el.dataset.id});return;}
if(act==="select-part"){const id=el.dataset.component;if(run("SELECT_PART",{componentId:id}))app.querySelector('[data-act="place"]:not(:disabled)')?.focus();return;}
if(act==="place"){if(run("PLACE",{slot:el.dataset.slot}))app.querySelector('[data-act="select-part"]:not(:disabled)')?.focus();return;}
if(act==="complete"){run("COMPLETE_STAGE");return;}
if(act==="retry"){prepState.key="";run("RETRY");return;}
if(act==="cancel"){if(confirm("調理を破棄しますか？ 食材は戻りません。"))run("CANCEL_ORDER");return;}
if(act==="serve"){run("SERVE");return;}
if(act==="advance-reaction"){run("REACTION_NEXT");return;}
if(act==="skip-reaction"){run("REACTION_SKIP");return;}
if(act==="dismiss"){run("DISMISS_REACTION");return;}

if(act==="upgrades"){run("GO_UPGRADE");return;}
if(act==="buy-upgrade"){run("BUY_UPGRADE",{id:el.dataset.id});return;}
if(act==="next-day"){if(run("NEXT_DAY")){resetDraft();}return;}
});
let coatHoldTimer=null,coatHoldTarget=null,coatHoldFired=false;document.addEventListener("keydown",e=>{const keyTarget=e.target;const editing=keyTarget instanceof HTMLElement&&(keyTarget.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(keyTarget.tagName));if(e.key==="Escape"){if(screen==="SETTINGS"){e.preventDefault();screen=settingsReturnScreen;render();return;}if(screen==="HELP"||screen==="CREDITS"){e.preventDefault();screen="TITLE";render();return;}if(screen==="GAME"&&game?.activeStoryEventId){e.preventDefault();continueStoryEvent();return;}if(screen==="GAME"&&game){e.preventDefault();if(game.overlay)run("RESUME");else{cancelTransientInput();run("PAUSE");}return;}}if((screen==="CREDITS"||screen==="SETTINGS")&&e.key==="Tab"){const dialog=app.querySelector('[role="dialog"][aria-modal="true"]'),focusable=dialog?[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex]:not([tabindex="-1"])')]:[],first=focusable[0],last=focusable.at(-1);if(!focusable.length){e.preventDefault();return;}if(e.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){e.preventDefault();first.focus();}return;}if(editing||e.altKey||e.ctrlKey||e.metaKey)return;if((e.key==="r"||e.key==="R")&&!e.repeat&&game?.phase==="COOK"&&!game.overlay){run("RETRY");return;}if((e.key==="Enter"||e.key===" ")&&document.activeElement?.classList.contains("meat-zone")){e.preventDefault();if(e.repeat)return;const t=config.cooking.p1TargetsX[game.cookingSession.stageInput.taps];if(t!==undefined)run("STRIKE",{x:t});return;}const zone=document.activeElement?.closest?.(".coat-zone");if((e.key==="Enter"||e.key===" ")&&zone&&game?.phase==="COOK"&&game.cookingSession?.stageIndex===1&&!game.overlay){e.preventDefault();if(e.repeat)return;coatHoldTarget=Number(zone.dataset.zone);coatHoldFired=false;coatHoldTimer=setTimeout(()=>{coatHoldFired=true;run("COAT",{zone:coatHoldTarget,full:true});},600);}});
document.addEventListener("keyup",e=>{if((e.key==="Enter"||e.key===" ")&&coatHoldTimer!==null){clearTimeout(coatHoldTimer);coatHoldTimer=null;if(!coatHoldFired&&game?.phase==="COOK"&&game.cookingSession?.stageIndex===1&&!game.overlay)run("COAT",{zone:coatHoldTarget});coatHoldTarget=null;}});
function cancelTransientInput(){if(coatStroke)finishCoatStroke(false);if(coatHoldTimer!==null){clearTimeout(coatHoldTimer);coatHoldTimer=null;coatHoldTarget=null;coatHoldFired=false;}}
function pauseOnFocusLoss(){if(screen!=="GAME"||!game||game.overlay||game.activeStoryEventId)return;cancelTransientInput();run("PAUSE");}
document.addEventListener("visibilitychange",()=>{if(document.hidden)pauseOnFocusLoss();});
window.addEventListener("blur",pauseOnFocusLoss);
setInterval(()=>{const now=Date.now();if(!lastUiTick){lastUiTick=now;return;}let delta=(now-lastUiTick)/1000;lastUiTick=now;if(screen!=="GAME"||!game||game.overlay)return;if(delta>0.3){run("PAUSE");notify("画面復帰後は再開ボタンを押してください");return;}accumulated+=delta;let frameChanged=false;while(accumulated>=0.1){const r=dispatch(game,{type:"TICK",payload:{seconds:0.1}},config);if(r.ok&&r.changed){game=r.state;saveDirty=true;dirtyVersion++;frameChanged=true;}accumulated-=0.1;}if(!document.hidden&&frameChanged&&!coatStroke&&!prepStroke)render();if(saveDirty&&now-lastSaveAt>2000&&game)save().catch(()=>{});},100);
async function boot(){try{loadSettings();const [configResponse,schemaResponse,dialogueResponse,storyResponse]=await Promise.all([fetch("./spec/mvp_config.json"),fetch("./spec/mvp_save.schema.json"),fetch("./spec/customer_dialogue_ja.json"),fetch("./spec/story_events_ja.json")]);if(!configResponse.ok||!schemaResponse.ok||!dialogueResponse.ok||!storyResponse.ok)throw Error("ゲーム設定・セーブ仕様・会話データを読み込めません");[config,saveSchema,customerDialogue,storyEvents]=await Promise.all([configResponse.json(),schemaResponse.json(),dialogueResponse.json(),storyResponse.json().then(data=>data.events)]);preloadArt();try{const stored=await dbRead();savedGameExists=stored.main.value!==undefined||stored.backup.value!==undefined;if(savedGameExists&&stored.main.errors.length&&stored.backup.errors.length)toast="保存データを検証できませんでした。つづきからを選ぶと詳細を確認できます。";await dbProbeWrite();}catch{storageWriteAvailable=false;if(!toast)toast="セーブ機能が使えない可能性があります。開始前に確認してください。";}render();if(screen==="TITLE")app.querySelector('[data-act="new"]')?.focus();}catch(e){app.innerHTML='<main class="help-page"><h1>読み込みエラー</h1><p>'+escapeHTML(e.message)+'</p><p>ローカルHTTPサーバーで実行してください（npm run dev）。</p></main>';}}
boot();
